30	import org.slf4j.Logger;
31	import org.slf4j.LoggerFactory;
32	import org.springframework.http.HttpHeaders;
33	import org.springframework.http.HttpStatus;
34	import org.springframework.http.ResponseEntity;
35	import org.springframework.samples.petclinic.mapper.OwnerMapper;
36	import org.springframework.samples.petclinic.mapper.PetMapper;
37	import org.springframework.samples.petclinic.mapper.VisitMapper;
38	import org.springframework.samples.petclinic.model.Owner;
39	import org.springframework.samples.petclinic.model.Pet;
40	import org.springframework.samples.petclinic.model.Visit;
41	import org.springframework.samples.petclinic.rest.advice.CityAtCapacityException;
42	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
43	import org.springframework.samples.petclinic.rest.advice.DuplicateIdentityException;
44	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
45	import org.springframework.samples.petclinic.rest.advice.InvalidPostcodeException;
46	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
47	import org.springframework.samples.petclinic.rest.advice.RequiredFieldsMissingException;
48	import org.springframework.samples.petclinic.rest.api.OwnersApi;
49	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
50	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
51	import org.springframework.samples.petclinic.rest.dto.PetDto;
52	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
53	import org.springframework.samples.petclinic.rest.dto.VisitDto;
54	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
55	import org.springframework.samples.petclinic.service.ClinicService;
56	import org.springframework.security.access.prepost.PreAuthorize;
57	import org.springframework.web.bind.annotation.CrossOrigin;
58	import org.springframework.web.bind.annotation.RequestMapping;
59	import org.springframework.web.bind.annotation.RestController;
60	import org.springframework.web.util.UriComponentsBuilder;
61	
62	import jakarta.transaction.Transactional;
63	
64	/**
65	 * @author Vitaliy Fedoriv
66	 */
67	
68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    /**
74	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that
75	     * contains at least one dot, with no whitespace anywhere. Deliberately lenient — it accepts
76	     * ordinary addresses while rejecting clearly malformed ones such as {@code not-an-email}.
77	     */
78	    private static final Pattern EMAIL_PATTERN =
79	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
80	
81	    /**
82	     * Dedicated audit logger. On a successful create an audit line carrying the owner id, the
83	     * customerCode, the registrationDate and the membershipLevel is emitted through this logger.
84	     */
85	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
86	
87	    private final ClinicService clinicService;
88	
89	    private final OwnerMapper ownerMapper;
90	
91	    private final PetMapper petMapper;
92	
93	    private final VisitMapper visitMapper;
94	
95	    public OwnerRestControllerV1(ClinicService clinicService,
96	                                 OwnerMapper ownerMapper,
97	                                 PetMapper petMapper,
98	                                 VisitMapper visitMapper) {
99	        this.clinicService = clinicService;
100	        this.ownerMapper = ownerMapper;
101	        this.petMapper = petMapper;
102	        this.visitMapper = visitMapper;
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
108	        Collection<Owner> owners;
109	        if (lastName != null) {
110	            owners = this.clinicService.findOwnerByLastName(lastName);
111	        } else {
112	            owners = this.clinicService.findAllOwners();
113	        }
114	        if (owners.isEmpty()) {
115	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
116	        }
117	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
118	    }
119	
120	    /**
121	     * Rejects an owner payload that is missing or blank in any required field, listing the name of
122	     * each offending field so the caller receives a 400 with a populated {@code errors} array.
123	     */
124	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
125	        List<String> missing = new ArrayList<>();
126	        if (isBlank(ownerFieldsDto.getFirstName())) {
127	            missing.add("firstName");
128	        }
129	        if (isBlank(ownerFieldsDto.getLastName())) {
130	            missing.add("lastName");
131	        }
132	        if (isBlank(ownerFieldsDto.getAddress())) {
133	            missing.add("address");
134	        }
135	        if (isBlank(ownerFieldsDto.getCity())) {
136	            missing.add("city");
137	        }
138	        if (isBlank(ownerFieldsDto.getTelephone())) {
139	            missing.add("telephone");
140	        }
141	        if (!missing.isEmpty()) {
142	            throw new RequiredFieldsMissingException(missing);
143	        }
144	    }
145	
146	    private static boolean isBlank(String value) {
147	        return value == null || value.isBlank();
148	    }
149	
150	    /**
151	     * Normalizes an address on create: leading/trailing whitespace is trimmed, every run of internal
152	     * whitespace is collapsed to a single space, the value is upper-cased and common abbreviations are
153	     * expanded token-by-token ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The
154	     * normalized value is what gets stored, returned and used for every address comparison; a value
155	     * that is blank (or {@code null}) normalizes to the empty string so the required-field check
156	     * rejects it.
157	     *
158	     * @param address the raw address as supplied by the caller, may be {@code null}
159	     * @return the normalized address ({@code ""} when blank or {@code null})
160	     */
161	    private static String normalizeAddress(String address) {
162	        if (address == null) {
163	            return "";
164	        }
165	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
166	        if (collapsed.isEmpty()) {
167	            return "";
168	        }
169	        String[] tokens = collapsed.split(" ");
170	        StringBuilder sb = new StringBuilder(collapsed.length());
171	        for (int i = 0; i < tokens.length; i++) {
172	            String token = tokens[i];
173	            switch (token) {
174	                case "ST" -> token = "STREET";
175	                case "RD" -> token = "ROAD";
176	                case "AVE" -> token = "AVENUE";
177	                default -> { }
178	            }
179	            if (i > 0) {
180	                sb.append(' ');
181	            }
182	            sb.append(token);
183	        }
184	        return sb.toString();
185	    }
186	
187	    /**
188	     * Normalizes a telephone on create into E.164 form. Spaces, dashes and brackets are stripped.
189	     * A leading {@code +} and its country code are kept as given; otherwise the country code
190	     * {@code +61} is assumed and a single leading {@code 0} is dropped from the national digits.
191	     * The result must carry 8 to 15 digits after the {@code +}. In addition, when the country code
192	     * is recognized the national number must have the exact length that code requires ({@code +61}
193	     * expects 9 national digits, {@code +1} expects 10). Returns the E.164 string to be stored and
194	     * returned.
195	     *
196	     * @param telephone the raw telephone as supplied by the caller
197	     * @return the normalized E.164 telephone (a {@code +} followed by 8 to 15 digits)
198	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
199	     *     national-number length is wrong for its country code
200	     */
201	    private static String normalizeTelephone(String telephone) {
202	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
203	        String e164;
204	        if (cleaned.startsWith("+")) {
205	            e164 = "+" + cleaned.substring(1);
206	        } else {
207	            String national = cleaned;
208	            if (national.startsWith("0")) {
209	                national = national.substring(1);
210	            }
211	            e164 = "+61" + national;
212	        }
213	        String digits = e164.substring(1);
214	        if (!digits.matches("\\d{8,15}")) {
215	            throw new InvalidTelephoneException(
216	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
217	        }
218	        if (digits.startsWith("61")) {
219	            requireNationalLength(digits.substring(2), 9, "+61");
220	        } else if (digits.startsWith("1")) {
221	            requireNationalLength(digits.substring(1), 10, "+1");
222	        }
223	        return e164;
224	    }
225	
226	    /**
227	     * Enforces that the national portion of an E.164 number has the exact number of digits its
228	     * country code requires.
229	     *
230	     * @param national the national-number digits (the part after the country code)
231	     * @param expected the exact national-number length the country code requires
232	     * @param countryCode the country code, for the error message
233	     * @throws InvalidTelephoneException if {@code national} does not have exactly {@code expected} digits
234	     */
235	    private static void requireNationalLength(String national, int expected, String countryCode) {
236	        if (national.length() != expected) {
237	            throw new InvalidTelephoneException(
238	                "Telephone with country code '" + countryCode + "' must have " + expected
239	                    + " national digits");
240	        }
241	    }
242	
243	    /**
244	     * Normalizes an optional email. An absent or blank email is left unset (returns {@code null});
245	     * a present value must be a syntactically valid address and is stored and returned lower-cased.
246	     *
247	     * @param email the raw email as supplied by the caller, may be {@code null}
248	     * @return the lower-cased email, or {@code null} when none was supplied
249	     * @throws InvalidEmailException if a value is present but is not a syntactically valid address
250	     */
251	    private static String normalizeEmail(String email) {
252	        if (email == null || email.isBlank()) {
253	            return null;
254	        }
255	        String trimmed = email.trim();
256	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
257	            throw new InvalidEmailException("Email must be a syntactically valid address");
258	        }
259	        return trimmed.toLowerCase(Locale.ROOT);
260	    }
261	
262	    /**
263	     * Derives the single duplicate-detection key that consolidates the former separate telephone,
264	     * email and household checks. The key is {@code normalizedTelephone + '|' + email + '|' +
265	     * householdId}, where the email segment is the empty string when the owner has no email. Because
266	     * the telephone is part of the key, two owners that differ in any one segment (for example two
267	     * members of the same household with different telephones) produce different keys.
268	     *
269	     * @param normalizedTelephone the E.164 telephone of the owner
270	     * @param email the lower-cased email of the owner, may be {@code null}
271	     * @param householdId the stable household identifier of the owner, may be {@code null}
272	     * @return the derived identity key
273	     */
274	    private static String deriveIdentityKey(String normalizedTelephone, String email, String householdId) {
275	        return (normalizedTelephone == null ? "" : normalizedTelephone)
276	            + "|" + (email == null ? "" : email)
277	            + "|" + (householdId == null ? "" : householdId);
278	    }
279	
280	    /**
281	     * Rejects a create only when the new owner's whole {@code identityKey} equals that of an existing
282	     * owner. This one check replaces the former separate telephone, email and household duplicate
283	     * checks: only an exact full-key match is a duplicate, so two owners that differ in any single
284	     * segment are both allowed. Each existing owner's key is derived from its stored, already
285	     * normalized telephone, email and household identifier.
286	     *
287	     * @param identityKey the derived identity key of the owner being created
288	     * @throws DuplicateIdentityException if another owner already has this identity key
289	     */
290	    private void rejectDuplicateIdentity(String identityKey) {
291	        boolean inUse = this.clinicService.findAllOwners().stream()
292	            .anyMatch(existing -> identityKey.equals(
293	                deriveIdentityKey(existing.getTelephone(), existing.getEmail(), existing.getHouseholdId())));
294	        if (inUse) {
295	            throw new DuplicateIdentityException(
296	                "An owner with the same identity key already exists");
297	        }
298	    }
299	
300	    /**
301	     * Normalizes a value for household comparison by trimming, collapsing every run of whitespace to
302	     * a single space and lower-casing, so the comparison is case-insensitive with collapsed whitespace.
303	     *
304	     * @param value the raw value, may be {@code null}
305	     * @return the normalized value ({@code ""} when {@code value} is {@code null})
306	     */
307	    private static String normalizeForHousehold(String value) {
308	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
309	    }
310	
311	    /**
312	     * Derives the stable household identifier for an owner from the normalized last name and address.
313	     * The value is a deterministic function of those two fields (compared case-insensitively with
314	     * collapsed whitespace), so every owner in the same
315	     * household — including owners who knowingly join it via {@code sharesHousehold} — is assigned the
316	     * same identifier without any existing record having to be updated. Formatted {@code 'HH-<HEX12>'}
317	     * where {@code HEX12} is the upper-cased first twelve hex characters of the SHA-256 of the two
318	     * normalized fields.
319	     *
320	     * @param lastName the last name of the owner being created
321	     * @param address the address of the owner being created
322	     * @return the stable household identifier
323	     */
324	    private static String householdId(String lastName, String address) {
325	        String key = normalizeForHousehold(lastName) + "\n" + normalizeForHousehold(address);
326	        try {
327	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
328	            StringBuilder sb = new StringBuilder(digest.length * 2);
329	            for (byte b : digest) {
330	                sb.append(String.format("%02x", b));
331	            }
332	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
333	        } catch (NoSuchAlgorithmException e) {
334	            throw new IllegalStateException("SHA-256 not available", e);
335	        }
336	    }
337	
338	    /**
339	     * The maximum number of owners a single city may contain. A create whose city already holds this
340	     * many owners is rejected, so a city never grows beyond this capacity.
341	     */
342	    private static final int CITY_CAPACITY = 50;
343	
344	    /**
345	     * Rejects a create whose city already contains {@link #CITY_CAPACITY} or more owners, so no city
346	     * ever exceeds its capacity. Cities are compared case-insensitively with surrounding whitespace
347	     * trimmed, exactly as {@link #nextCustomerCode} counts a city's owners. The count reflects the
348	     * state before the new owner is persisted, so it excludes the owner being created.
349	     *
350	     * @param city the city of the owner being created
351	     * @throws CityAtCapacityException if the city already contains {@link #CITY_CAPACITY} owners
352	     */
353	    private void rejectCityAtCapacity(String city) {
354	        String normalizedCity = normalizeName(city);
355	        long ownersInCity = this.clinicService.findAllOwners().stream()
356	            .filter(existing -> normalizedCity.equals(normalizeName(existing.getCity())))
357	            .count();
358	        if (ownersInCity >= CITY_CAPACITY) {
359	            throw new CityAtCapacityException(
360	                "The city already contains the maximum number of owners");
361	        }
362	    }
363	
364	    /**
365	     * The maximum number of owners that may be created on a single day. A create made once this many
366	     * owners already carry today's {@code registrationDate} is rejected, so no more than this many
367	     * owners are registered per day.
368	     */
369	    private static final int DAILY_OWNER_LIMIT = 100;
370	
371	    /**
372	     * Rejects a create once {@link #DAILY_OWNER_LIMIT} or more owners have already been created for
373	     * the given business day, counted by {@code registrationDate} equal to the effective (weekend
374	     * rolled forward) registration date of the owner being created. The count reflects the state
375	     * before the new owner is persisted, so it excludes the owner being created.
376	     *
377	     * @param registrationDate the effective business-day registration date of the owner being created
378	     * @throws DailyOwnerLimitExceededException if the day already holds {@link #DAILY_OWNER_LIMIT} owners
379	     */
380	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
381	        long ownersToday = this.clinicService.findAllOwners().stream()
382	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
383	            .count();
384	        if (ownersToday >= DAILY_OWNER_LIMIT) {
385	            throw new DailyOwnerLimitExceededException(
386	                "The maximum number of owners for today has already been reached");
387	        }
388	    }
389	
390	    /**
391	     * The number of owners that may already exist for a business day before a create is flagged with
392	     * a bulk-signup warning. Once more than this many owners already carry the effective registration
393	     * date, the created owner's {@code bulkSignupWarning} is set to {@code true}.
394	     */
395	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
396	
397	    /**
398	     * Determines whether a create should be flagged with a bulk-signup warning, i.e. whether more than
399	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for the given business day,
400	     * counted by {@code registrationDate} equal to the effective (weekend rolled forward) registration
401	     * date of the owner being created. The count reflects the state before the new owner is persisted,
402	     * so it excludes the owner being created.
403	     *
404	     * @param registrationDate the effective business-day registration date of the owner being created
405	     * @return {@code true} when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the date
406	     */
407	    private boolean bulkSignupWarning(LocalDate registrationDate) {
408	        long ownersToday = this.clinicService.findAllOwners().stream()
409	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
410	            .count();
411	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
412	    }
413	
414	    /**
415	     * Rolls a registration date forward to a business day: a Saturday or Sunday is advanced to the
416	     * following Monday, any weekday is returned unchanged.
417	     *
418	     * @param date the effective registration date, supplied or defaulted to the server date
419	     * @return the same date when it is a weekday, otherwise the next Monday
420	     */
421	    private static LocalDate toBusinessDay(LocalDate date) {
422	        DayOfWeek dayOfWeek = date.getDayOfWeek();
423	        if (dayOfWeek == DayOfWeek.SATURDAY) {
424	            return date.plusDays(2);
425	        }
426	        if (dayOfWeek == DayOfWeek.SUNDAY) {
427	            return date.plusDays(1);
428	        }
429	        return date;
430	    }
431	
432	    /**
433	     * Builds the customer code assigned to an owner on create, formatted
434	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first three letters
435	     * of the owner's city, {@code LAST3} is the upper-cased first three letters of the owner's last
436	     * name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the
437	     * current number of owners already in that city, e.g. {@code 'MEL-SMI-0007'}.
438	     *
439	     * @param city the city of the owner being created
440	     * @param lastName the last name of the owner being created
441	     * @return the formatted customer code
442	     */
443	    private String nextCustomerCode(String city, String lastName) {
444	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
445	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
446	        String normalizedCity = normalizeName(city);
447	        int sequence = (int) this.clinicService.findAllOwners().stream()
448	            .filter(existing -> normalizedCity.equals(normalizeName(existing.getCity())))
449	            .count() + 1;
450	        return String.format("%s-%s-%04d", city3, last3, sequence);
451	    }
452	
453	    /**
454	     * Counts the existing owners that share the owner-to-be's first and last name, compared
455	     * case-insensitively (surrounding whitespace trimmed). The count reflects the state before the
456	     * new owner is persisted, so it excludes the owner being created.
457	     *
458	     * @param firstName the first name of the owner being created
459	     * @param lastName the last name of the owner being created
460	     * @return the number of existing owners with the same first and last name
461	     */
462	    private int countNamesakes(String firstName, String lastName) {
463	        String normalizedFirstName = normalizeName(firstName);
464	        String normalizedLastName = normalizeName(lastName);
465	        return (int) this.clinicService.findAllOwners().stream()
466	            .filter(existing ->
467	                normalizedFirstName.equals(normalizeName(existing.getFirstName()))
468	                    && normalizedLastName.equals(normalizeName(existing.getLastName())))
469	            .count();
470	    }
471	
472	    /**
473	     * Counts the members of the owner-to-be's household after this create, i.e. one more than the
474	     * number of existing owners already carrying the same {@code householdId}. A household identifier
475	     * is only assigned to owners who knowingly share a household via {@code sharesHousehold}; a solo
476	     * owner has no household identifier ({@code null}) and is therefore always a household of one. The
477	     * count includes the owner being created (hence the {@code + 1}).
478	     *
479	     * @param householdId the stable household identifier of the owner being created, or {@code null}
480	     *     when the owner does not share a household
481	     * @return the number of household members after this create (always at least 1)
482	     */
483	    private int householdSize(String householdId) {
484	        if (householdId == null) {
485	            return 1;
486	        }
487	        return (int) this.clinicService.findAllOwners().stream()
488	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
489	            .count() + 1;
490	    }
491	
492	    /**
493	     * Normalizes a name for case-insensitive comparison by trimming surrounding whitespace and
494	     * lower-casing.
495	     *
496	     * @param value the raw name, may be {@code null}
497	     * @return the normalized name ({@code ""} when {@code value} is {@code null})
498	     */
499	    private static String normalizeName(String value) {
500	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
501	    }
502	
503	    /**
504	     * The fixed city-to-region table used to validate a postcode against its city
505	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD). A city not in this table has no known region and
506	     * therefore accepts any 4-digit postcode.
507	     */
508	    private static final java.util.Map<String, String> CITY_REGION = java.util.Map.of(
509	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
510	
511	    /**
512	     * The fixed region-to-postcode-range table: each region admits an inclusive 4-digit range
513	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
514	     */
515	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
516	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
517	
518	    /**
519	     * Validates an owner's optional postcode on create. A {@code null} or blank postcode is left
520	     * untouched (postcode is optional when absent). When present it must be exactly four digits and,
521	     * when the city maps to a known region, must fall within that region's inclusive range
522	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
523	     * postcode.
524	     *
525	     * @param city the city of the owner being created
526	     * @param postcode the raw postcode as supplied by the caller, may be {@code null}
527	     * @throws InvalidPostcodeException if a present postcode is not four digits or is out of range
528	     *     for the city's region
529	     */
530	    private static void validatePostcode(String city, String postcode) {
531	        if (postcode == null || postcode.isBlank()) {
532	            return;
533	        }
534	        if (!postcode.matches("\\d{4}")) {
535	            throw new InvalidPostcodeException("Postcode must be exactly 4 digits");
536	        }
537	        String region = CITY_REGION.get(city);
538	        int[] range = region == null ? null : REGION_POSTCODES.get(region);
539	        if (range != null) {
540	            int value = Integer.parseInt(postcode);
541	            if (value < range[0] || value > range[1]) {
542	                throw new InvalidPostcodeException(
543	                    "Postcode is out of range for the city's region");
544	            }
545	        }
546	    }
547	
548	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
549	    @Override
550	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
551	        Owner owner = this.clinicService.findOwnerById(ownerId);
552	        if (owner == null) {
553	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
554	        }
555	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
556	    }
557	
558	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
559	    @Override
560	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
561	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
562	        validateRequiredFields(ownerFieldsDto);
563	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
564	        if (registrationDate == null) {
565	            registrationDate = LocalDate.now();
566	        }
567	        registrationDate = toBusinessDay(registrationDate);
568	        ownerFieldsDto.setRegistrationDate(registrationDate);
569	        rejectDailyOwnerLimit(registrationDate);
570	        rejectCityAtCapacity(ownerFieldsDto.getCity());
571	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
572	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
573	        ownerFieldsDto.setTelephone(normalizedTelephone);
574	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
575	        ownerFieldsDto.setEmail(normalizedEmail);
576	        String ownerHouseholdId = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
577	            ? householdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress())
578	            : null;
579	        rejectDuplicateIdentity(deriveIdentityKey(normalizedTelephone, normalizedEmail, ownerHouseholdId));
580	        HttpHeaders headers = new HttpHeaders();
581	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
582	        owner.setCustomerCode(nextCustomerCode(ownerFieldsDto.getCity(), ownerFieldsDto.getLastName()));
583	        owner.setHouseholdId(ownerHouseholdId);
584	        owner.setHouseholdSize(householdSize(ownerHouseholdId));
585	        owner.setNamesakeCount(countNamesakes(ownerFieldsDto.getFirstName(), ownerFieldsDto.getLastName()));
586	        owner.setBulkSignupWarning(bulkSignupWarning(registrationDate));
587	        this.clinicService.saveOwner(owner);
588	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
589	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
590	            ownerMapper.membershipLevel(owner));
591	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
592	        headers.setLocation(UriComponentsBuilder.newInstance()
593	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
594	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
595	    }
596	
597	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
598	    @Override
599	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
600	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
601	        if (currentOwner == null) {
602	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
603	        }
604	        currentOwner.setAddress(ownerFieldsDto.getAddress());
605	        currentOwner.setCity(ownerFieldsDto.getCity());
606	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
607	        currentOwner.setLastName(ownerFieldsDto.getLastName());
608	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
609	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
610	        this.clinicService.saveOwner(currentOwner);
611	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
612	    }
613	
614	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
615	    @Transactional
616	    @Override
617	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
618	        Owner owner = this.clinicService.findOwnerById(ownerId);
619	        if (owner == null) {
620	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
621	        }
622	        this.clinicService.deleteOwner(owner);
623	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
624	    }
625	
626	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
627	    @Override
628	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
629	        Owner owner = this.clinicService.findOwnerById(ownerId);
630	        if (owner == null) {
631	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
632	        }
633	        HttpHeaders headers = new HttpHeaders();
634	        Pet pet = petMapper.toPet(petFieldsDto);
635	        owner.setId(ownerId);
636	        pet.setOwner(owner);
637	        pet.getType().setName(null);
638	        this.clinicService.savePet(pet);
639	        PetDto petDto = petMapper.toPetDto(pet);
640	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
641	            .buildAndExpand(pet.getId()).toUri());
642	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
643	    }
644	
645	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
646	    @Override
647	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
648	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
649	        if (currentOwner != null) {
650	            Pet currentPet = this.clinicService.findPetById(petId);
651	            if (currentPet != null) {
652	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
653	                currentPet.setName(petFieldsDto.getName());
654	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
655	                this.clinicService.savePet(currentPet);
656	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
657	            }
658	        }
659	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
660	    }
661	
662	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
663	    @Override
664	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
665	        HttpHeaders headers = new HttpHeaders();
666	        Visit visit = visitMapper.toVisit(visitFieldsDto);
667	        Pet pet = new Pet();
668	        pet.setId(petId);
669	        visit.setPet(pet);
670	        this.clinicService.saveVisit(visit);
671	        VisitDto visitDto = visitMapper.toVisitDto(visit);
672	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
673	            .buildAndExpand(visit.getId()).toUri());
674	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
675	    }
676	
677	
678	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
679	    @Override
680	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
681	        Owner owner = this.clinicService.findOwnerById(ownerId);
682	        if (owner != null) {
683	            Pet pet = owner.getPet(petId);
684	            if (pet != null) {
685	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
686	            }
687	        }
688	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
689	    }
690	}
